window.QB_TWK_B12 = [
{id:"TWK-1801",q:"Pengamalan sila pertama Pancasila dalam kehidupan sehari-hari diwujudkan melalui perilaku ....",opts:["menjalankan ibadah sesuai agama dan kepercayaan masing-masing","mengikuti gotong royong membersihkan lingkungan","menghargai pendapat orang lain dalam musyawarah","membantu korban bencana alam tanpa pamrih","menjunjung tinggi persatuan dan kesatuan bangsa"],a:0,ex:"Sila pertama (Ketuhanan Yang Maha Esa) menuntut penghormatan pada kebebasan beragama dan pelaksanaan ibadah; gotong royong mencerminkan sila ketiga/kelima, musyawarah sila keempat, menolong korban sila kedua."},
{id:"TWK-1802",q:"BPUPKI sebagai badan penyelidik persiapan kemerdekaan dibentuk oleh pemerintah Jepang pada tanggal ....",opts:["29 April 1945","1 Juni 1945","22 Juni 1945","18 Agustus 1945","17 Agustus 1945"],a:0,ex:"BPUPKI (Dokuritsu Junbi Cosakai) dibentuk 29 April 1945; sidang pertamanya 29 Mei-1 Juni 1945. Tanggal 1 Juni adalah pidato Soekarno, 22 Juni Piagam Jakarta, 18 Agustus sidang PPKI."},
{id:"TWK-1803",q:"Tokoh yang mengusulkan lima asas dasar negara dalam sidang BPUPKI tanggal 29 Mei 1945 adalah ....",opts:["Mr. Muhammad Yamin","Mr. Soepomo","Ir. Soekarno","Drs. Mohammad Hatta","Mr. Soebarjo"],a:0,ex:"Mr. Muhammad Yamin berpidato 29 Mei 1945 dengan lima asas (peri kebangsaan, peri kemanusiaan, peri ketuhanan, peri kerakyatan, kesejahteraan rakyat); Soepomo 31 Mei, Soekarno 1 Juni."},
{id:"TWK-1804",q:"Salah satu dari lima asas dasar negara usulan Mr. Soepomo dalam sidang BPUPKI adalah ....",opts:["keseimbangan lahir dan batin","peri kebangsaan","peri ketuhanan","kebangsaan Indonesia","internasionalisme atau peri kemanusiaan"],a:0,ex:"Usulan Soepomo (31 Mei 1945): persatuan, kekeluargaan, keseimbangan lahir-batin, musyawarah, keadilan rakyat. Peri kebangsaan/ketuhanan milik Yamin; kebangsaan Indonesia dan internasionalisme milik Soekarno."},
{id:"TWK-1805",q:"Istilah 'Pancasila' pertama kali dikemukakan Ir. Soekarno dalam pidatonya di depan sidang BPUPKI pada ....",opts:["1 Juni 1945","29 Mei 1945","22 Juni 1945","18 Agustus 1945","17 Agustus 1945"],a:0,ex:"Soekarno berpidato 1 Juni 1945 mengusulkan lima sila dan menyebutnya Pancasila atas saran ahli bahasa. Tanggal ini diperingati sebagai Hari Lahir Pancasila."},
{id:"TWK-1806",q:"Rumusan dasar negara oleh Panitia Sembilan pada 22 Juni 1945 yang menjadi cikal bakal sila-sila Pancasila dikenal sebagai ....",opts:["Piagam Jakarta","Piagam Madinah","Naskah Proklamasi","Teks Sumpah Pemuda","Deklarasi Djuanda"],a:0,ex:"Panitia Sembilan merumuskan Piagam Jakarta (Jakarta Charter) 22 Juni 1945 sebagai cikal bakal Pembukaan UUD 1945. Pilihan lain adalah dokumen bersejarah yang berbeda konteksnya."},
{id:"TWK-1807",q:"Tujuh kata dalam sila pertama Piagam Jakarta yang kemudian diubah oleh PPKI adalah ....",opts:["dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya","Ketuhanan dengan kewajiban menjalankan syariat Islam","dengan kewajiban menjalankan syariat bagi seluruh rakyat","Ketuhanan Yang Maha Esa bagi pemeluk agama","kewajiban menjalankan ibadah bagi pemeluknya"],a:0,ex:"Bunyi asli sila pertama Piagam Jakarta memuat tujuh kata tersebut; demi persatuan, PPKI 18 Agustus 1945 menggantinya menjadi 'Ketuhanan Yang Maha Esa'."},
{id:"TWK-1808",q:"Sila pertama Pancasila hasil keputusan PPKI tanggal 18 Agustus 1945 berbunyi ....",opts:["Ketuhanan Yang Maha Esa","Ketuhanan dengan kewajiban menjalankan syariat Islam","Kemanusiaan yang adil dan beradab","Persatuan Indonesia","Kepercayaan terhadap Tuhan Yang Maha Esa"],a:0,ex:"PPKI mengesahkan rumusan final sila pertama: 'Ketuhanan Yang Maha Esa'. Rumusan dengan tujuh kata adalah versi Piagam Jakarta sebelum diubah."},
{id:"TWK-1809",q:"Jumlah helai bulu pada masing-masing sayap Garuda Pancasila yang melambangkan tanggal proklamasi adalah ....",opts:["17 helai","8 helai","45 helai","19 helai","20 helai"],a:0,ex:"Sayap 17 helai (tanggal), ekor 8 helai (bulan), leher 45 helai (tahun) melambangkan 17-8-1945. Angka lain tidak sesuai makna simbolik lambang negara."},
{id:"TWK-1810",q:"Delapan helai bulu ekor pada lambang Garuda Pancasila melambangkan ....",opts:["bulan Agustus","tanggal 17","tahun 1945","delapan penjuru mata angin","delapan sila Pancasila"],a:0,ex:"Ekor 8 helai = bulan ke-8 (Agustus). Tanggal dilambangkan sayap (17), tahun oleh bulu leher (45); Pancasila hanya lima sila."},
{id:"TWK-1811",q:"Tokoh yang merancang lambang negara Garuda Pancasila adalah ....",opts:["Sultan Hamid II","Mr. Soepomo","Ki Hajar Dewantara","Mr. Muhammad Yamin","R.M. Soeripto"],a:0,ex:"Sultan Hamid II (Pontianak) merancang Garuda Pancasila yang disempurnakan pelukis Dullah dan ditetapkan 11 Februari 1950. Tokoh lain tidak terlibat perancangan lambang."},
{id:"TWK-1812",q:"Semboyan Bhinneka Tunggal Ika pada lambang Garuda Pancasila terletak pada ....",opts:["pita yang dicengkeram kedua kaki Garuda","perisai di dada Garuda","paruh Garuda","kedua sayap Garuda","mahkota di kepala Garuda"],a:0,ex:"Kedua kaki Garuda mencengkeram pita bertuliskan Bhinneka Tunggal Ika; perisai memuat lima simbol sila, bukan semboyan."},
{id:"TWK-1813",q:"Perisai di dada Garuda Pancasila yang terbagi menjadi lima ruang melambangkan ....",opts:["kelima sila Pancasila sebagai perisai pertahanan bangsa","lima pulau besar Indonesia","lima agama resmi di Indonesia","lima unsur pimpinan negara","lima zaman perjuangan bangsa"],a:0,ex:"Lima ruang perisai memuat simbol tiap sila (bintang, rantai, beringin, banteng, padi-kapas) sebagai tameng ideologi bangsa, bukan pulau, agama, atau unsur lain."},
{id:"TWK-1814",q:"Seorang siswa menolong temannya yang terjatuh tanpa membedakan suku dan agamanya. Perilaku tersebut mencerminkan pengamalan Pancasila sila ....",opts:["kedua","pertama","ketiga","keempat","kelima"],a:0,ex:"Menolong sesama tanpa diskriminasi adalah nilai kemanusiaan (sila kedua: Kemanusiaan yang adil dan beradab); bukan ibadah (sila 1), persatuan (sila 3), musyawarah (sila 4), atau keadilan sosial (sila 5)."},
{id:"TWK-1815",q:"Warga dari berbagai suku bahu-membahu membangun jembatan desa secara gotong royong. Perilaku tersebut mencerminkan pengamalan Pancasila sila ....",opts:["ketiga","pertama","kedua","keempat","kelima"],a:0,ex:"Gotong royong lintas suku mewujudkan persatuan (sila ketiga: Persatuan Indonesia). Bukan sila ketuhanan, kemanusiaan, kerakyatan, maupun keadilan sosial."},
{id:"TWK-1816",q:"Pemilihan ketua kelas dilakukan melalui diskusi bersama hingga tercapai kesepakatan. Perilaku tersebut mencerminkan pengamalan Pancasila sila ....",opts:["keempat","pertama","kedua","ketiga","kelima"],a:0,ex:"Pengambilan keputusan lewat musyawarah mufakat adalah nilai kerakyatan (sila keempat). Bukan ibadah, kemanusiaan, persatuan, atau keadilan sosial."},
{id:"TWK-1817",q:"Pemerintah desa membagikan bantuan sosial secara merata tanpa membedakan latar belakang penerima. Kebijakan tersebut mencerminkan pengamalan Pancasila sila ....",opts:["kelima","pertama","kedua","ketiga","keempat"],a:0,ex:"Pemerataan bantuan mewujudkan keadilan sosial (sila kelima: Keadilan sosial bagi seluruh rakyat Indonesia), bukan sila ketuhanan, kemanusiaan, persatuan, atau kerakyatan."},
{id:"TWK-1818",q:"Sebutan ideologi terbuka bagi Pancasila didasarkan pada sifatnya yang ....",opts:["mampu mengikuti perkembangan zaman tanpa kehilangan nilai dasarnya","dapat diganti sewaktu-waktu sesuai kehendak penguasa","hanya berlaku bagi golongan tertentu","tertutup dari segala pengaruh asing","sama kedudukannya dengan ideologi liberalisme"],a:0,ex:"Ideologi terbuka berarti nilai dasar Pancasila tetap, tetapi penjabarannya dinamis mengikuti zaman. Pancasila tidak dapat diganti penguasa, berlaku universal, dan berbeda dari liberalisme."},
{id:"TWK-1819",q:"Makna kedudukan Pancasila sebagai dasar negara adalah ....",opts:["menjadi sumber dari segala sumber hukum dan pedoman penyelenggaraan negara","hanya menjadi simbol upacara kenegaraan","berkedudukan sama dengan peraturan perundang-undangan lain","berlaku khusus di lingkungan pemerintahan pusat","dapat ditafsirkan bebas tanpa batasan nilai"],a:0,ex:"Sebagai dasar negara, Pancasila adalah kaidah fundamental (sumber segala sumber hukum) yang menjiwai seluruh peraturan; bukan sekadar simbol atau aturan biasa yang bisa ditafsir sembarangan."},
{id:"TWK-1820",q:"Nilai yang terkandung dalam sila keempat Pancasila adalah ....",opts:["kerakyatan yang dipimpin oleh hikmat kebijaksanaan","ketakwaan terhadap Tuhan Yang Maha Esa","persamaan derajat antarmanusia","cinta tanah air dan bangsa","pemerataan kesejahteraan rakyat"],a:0,ex:"Sila keempat bernilai kerakyatan dan musyawarah; ketakwaan = sila 1, persamaan derajat = sila 2, cinta tanah air = sila 3, pemerataan = sila 5."},
{id:"TWK-1821",q:"Kesatuan sila-sila Pancasila yang bulat dan utuh mengandung pengertian bahwa ....",opts:["pengamalan satu sila harus dijiwai dan menjiwai sila-sila lainnya","setiap sila dapat diamalkan secara terpisah-pisah","sila pertama lebih tinggi kedudukannya dari sila lain","cukup mengamalkan satu sila yang paling mudah","sila-sila tersebut tidak saling berkaitan"],a:0,ex:"Sila Pancasila bersifat hierarkis-piramidal dan saling menjiwai; tidak boleh dipisah atau dipertentangkan, dan kedudukannya setara sebagai kesatuan."},
{id:"TWK-1822",q:"Jabatan ketua BPUPKI dipegang oleh ....",opts:["Dr. K.R.T. Radjiman Wedyodiningrat","Ir. Soekarno","Drs. Mohammad Hatta","Mr. Soepomo","Ichibangase Yosio"],a:0,ex:"Radjiman Wedyodiningrat menjadi ketua BPUPKI dengan wakil Ichibangase (Jepang). Soekarno-Hatta memimpin PPKI; Soepomo anggota BPUPKI."},
{id:"TWK-1823",q:"Tugas utama BPUPKI adalah ....",opts:["menyelidiki usaha-usaha persiapan kemerdekaan Indonesia","memproklamasikan kemerdekaan Indonesia","menyusun strategi perang Asia Timur Raya","membentuk tentara pembela tanah air","menjalankan pemerintahan pendudukan Jepang"],a:0,ex:"BPUPKI (Badan Penyelidik Usaha Persiapan Kemerdekaan) bertugas menyelidiki persiapan kemerdekaan; proklamasi dilakukan Soekarno-Hatta, bukan badan ini."},
{id:"TWK-1824",q:"Sidang PPKI tanggal 18 Agustus 1945 menghasilkan keputusan penting berupa ....",opts:["mengesahkan UUD 1945 serta memilih presiden dan wakil presiden","memproklamasikan kemerdekaan Indonesia","membentuk BPUPKI","menyusun Piagam Jakarta","membubarkan seluruh organisasi pergerakan"],a:0,ex:"Sidang PPKI 18 Agustus 1945 mengesahkan UUD 1945, memilih Soekarno-Hatta, dan membentuk KNIP. Proklamasi sudah terjadi 17 Agustus; BPUPKI dan Piagam Jakarta lebih dahulu."},
{id:"TWK-1825",q:"Pernyataan 'mengakui persamaan derajat serta hak dan kewajiban asasi setiap manusia' merupakan nilai Pancasila sila ....",opts:["kedua","pertama","ketiga","keempat","kelima"],a:0,ex:"Persamaan derajat manusia adalah nilai kemanusiaan (sila kedua), bukan ketuhanan (1), persatuan (3), kerakyatan (4), atau keadilan sosial (5)."},
{id:"TWK-1826",q:"Sikap cinta tanah air dan rela berkorban untuk kepentingan bangsa merupakan nilai Pancasila sila ....",opts:["ketiga","pertama","kedua","keempat","kelima"],a:0,ex:"Cinta tanah air dan rela berkorban adalah nilai persatuan (sila ketiga), bukan ketuhanan, kemanusiaan, kerakyatan, atau keadilan sosial."},
{id:"TWK-1827",q:"Kebiasaan mengutamakan musyawarah untuk mencapai mufakat dalam mengambil keputusan mencerminkan nilai Pancasila sila ....",opts:["keempat","pertama","kedua","ketiga","kelima"],a:0,ex:"Musyawarah mufakat adalah nilai kerakyatan (sila keempat), bukan ketuhanan, kemanusiaan, persatuan, atau keadilan sosial."},
{id:"TWK-1828",q:"Kegemaran melakukan kegiatan kemanusiaan seperti donor darah dan menolong korban bencana mencerminkan nilai Pancasila sila ....",opts:["kedua","pertama","ketiga","keempat","kelima"],a:0,ex:"Kegiatan kemanusiaan adalah pengamalan sila kedua (kemanusiaan yang adil dan beradab), bukan sila ketuhanan, persatuan, kerakyatan, atau keadilan sosial."},
{id:"TWK-1829",q:"Pancasila sebagai pandangan hidup bangsa mengandung arti ....",opts:["menjadi pedoman sikap dan perilaku dalam kehidupan sehari-hari","hanya menjadi bahan pelajaran di sekolah","berlaku terbatas pada acara-acara resmi negara","kedudukannya di bawah peraturan pemerintah","tidak berkaitan dengan kehidupan masyarakat"],a:0,ex:"Sebagai pandangan hidup (way of life), Pancasila menjiwai seluruh sikap dan perilaku warga, bukan sekadar bahan pelajaran atau aturan seremonial."},
{id:"TWK-1830",q:"Arah tolehan kepala Garuda Pancasila ke sebelah kanan melambangkan ....",opts:["bangsa Indonesia menjunjung kebajikan dan kebenaran","kegagahan burung garuda sebagai lambang negara","arah kiblat umat beragama di Indonesia","kekuasaan negara atas seluruh rakyat","kemenangan dalam setiap peperangan"],a:0,ex:"Kepala menoleh ke kanan melambangkan bangsa Indonesia selalu berpihak pada kebajikan; bukan sekadar kegagahan, arah kiblat, kekuasaan, atau kemenangan perang."},
{id:"TWK-1831",q:"Padi dan kapas pada perisai Garuda Pancasila menjadi simbol sila Pancasila ke ....",opts:["kelima","pertama","kedua","ketiga","keempat"],a:0,ex:"Padi-kapas = sandang-pangan (kemakmuran) simbol sila kelima (keadilan sosial); bintang = sila 1, rantai = sila 2, beringin = sila 3, banteng = sila 4."},
{id:"TWK-1832",q:"Kepala banteng pada perisai Garuda Pancasila merupakan simbol Pancasila sila ....",opts:["keempat","pertama","kedua","ketiga","kelima"],a:0,ex:"Banteng melambangkan tenaga rakyat/kerakyatan (sila keempat); bintang = sila 1, rantai = sila 2, beringin = sila 3, padi-kapas = sila 5."},
{id:"TWK-1833",q:"Gambar rantai pada perisai Garuda Pancasila merupakan simbol Pancasila sila ....",opts:["kedua","pertama","ketiga","keempat","kelima"],a:0,ex:"Rantai (mata rantai yang saling berkait) melambangkan hubungan manusia yang adil dan beradab (sila kedua); bukan simbol sila lainnya."},
{id:"TWK-1834",q:"Pohon beringin pada perisai Garuda Pancasila merupakan simbol Pancasila sila ....",opts:["ketiga","pertama","kedua","keempat","kelima"],a:0,ex:"Beringin yang kokoh dan menaungi melambangkan persatuan (sila ketiga); bintang = sila 1, rantai = sila 2, banteng = sila 4, padi-kapas = sila 5."},
{id:"TWK-1835",q:"Pembukaan UUD 1945 terdiri atas ....",opts:["empat alinea","tiga alinea","lima alinea","dua alinea","enam alinea"],a:0,ex:"Pembukaan UUD 1945 terdiri dari empat alinea yang memuat tujuan dan dasar negara. Jumlah lain tidak sesuai naskah aslinya."},
{id:"TWK-1836",q:"Alinea pertama Pembukaan UUD 1945 mengandung dalil ....",opts:["objektif","subjektif","teologis","historis","relatif"],a:0,ex:"Alinea pertama memuat dalil objektif (penjajahan di atas dunia harus dihapuskan karena tidak sesuai peri kemanusiaan); dalil subjektif ada pada alinea ketiga."},
{id:"TWK-1837",q:"Pokok pikiran 'negara melindungi segenap bangsa Indonesia dan seluruh tumpah darah Indonesia' tercantum dalam Pembukaan UUD 1945 alinea ....",opts:["keempat","pertama","kedua","ketiga","kelima"],a:0,ex:"Pokok pikiran persatuan/proteksi tercantum pada alinea keempat; alinea pertama tentang penjajahan, kedua cita-cita merdeka, ketiga pernyataan kemerdekaan."},
{id:"TWK-1838",q:"Pasal 27 ayat (2) UUD 1945 berbunyi ....",opts:["tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan","segala warga negara bersamaan kedudukannya di dalam hukum","kemerdekaan berserikat dan berkumpul mengeluarkan pikiran","hak untuk hidup serta mempertahankan kehidupan","fakir miskin dan anak terlantar dipelihara negara"],a:0,ex:"Pasal 27 ayat (2) menjamin hak atas pekerjaan dan penghidupan layak; kesamaan di hukum = ayat (1), berserikat = Pasal 28, hak hidup = Pasal 28A, fakir miskin = Pasal 34."},
{id:"TWK-1839",q:"Hak warga negara untuk berserikat, berkumpul, dan mengeluarkan pendapat dijamin dalam Pasal .... UUD 1945",opts:["28","27","29","30","31"],a:0,ex:"Pasal 28 UUD 1945 menjamin kemerdekaan berserikat dan berkumpul; Pasal 27 tentang hak warga negara umum, 29 agama, 30 pertahanan, 31 pendidikan."},
{id:"TWK-1840",q:"Jumlah amandemen yang telah dialami UUD 1945 adalah ....",opts:["empat kali","dua kali","tiga kali","lima kali","enam kali"],a:0,ex:"UUD 1945 diamandemen empat kali (1999, 2000, 2001, 2002) oleh MPR. Jumlah lain tidak sesuai fakta ketatanegaraan."},
{id:"TWK-1841",q:"Amandemen pertama UUD 1945 dilaksanakan pada tahun ....",opts:["1999","1998","2000","2001","2002"],a:0,ex:"Amandemen I ditetapkan 19 Oktober 1999 (9 pasal); amandemen II tahun 2000, III tahun 2001, IV tahun 2002."},
{id:"TWK-1842",q:"Lembaga negara yang berwenang mengubah dan menetapkan UUD 1945 adalah ....",opts:["MPR","DPR","DPD","Presiden","Mahkamah Konstitusi"],a:0,ex:"Pasal 37 UUD 1945 menegaskan MPR berwenang mengubah UUD; DPR legislasi, DPD pertimbangan daerah, MK menguji UU, presiden eksekutif."},
{id:"TWK-1843",q:"Fungsi legislasi yang dimiliki DPR berkaitan dengan ....",opts:["pembentukan undang-undang bersama presiden","pelaksanaan putusan pengadilan","pengangkatan duta besar","pemberian grasi dan rehabilitasi","penetapan hakim agung"],a:0,ex:"Fungsi legislasi = membentuk UU bersama presiden (Pasal 20); tiga fungsi DPR adalah legislasi, anggaran, pengawasan. Pilihan lain bukan fungsi DPR."},
{id:"TWK-1844",q:"Anggota DPD dipilih dari setiap provinsi sebanyak ....",opts:["empat orang","tiga orang","lima orang","dua orang","satu orang"],a:0,ex:"Pasal 22C UUD 1945: anggota DPD dari tiap provinsi empat orang, jumlah seluruhnya tidak lebih dari sepertiga anggota DPR."},
{id:"TWK-1845",q:"Objek pengujian undang-undang oleh Mahkamah Konstitusi adalah ....",opts:["UUD 1945","ketetapan MPR","peraturan pemerintah","peraturan daerah","keputusan presiden"],a:0,ex:"MK menguji UU terhadap UUD 1945 (judicial review); TAP MPR, PP, perda, dan keppres bukan objek pengujian MK."},
{id:"TWK-1846",q:"Perpu ditetapkan oleh presiden dalam hal ....",opts:["kegentingan yang memaksa","atas persetujuan DPR terlebih dahulu","setiap awal tahun anggaran","atas usul Mahkamah Agung","dalam keadaan negara aman dan damai"],a:0,ex:"Pasal 22 UUD 1945: presiden menetapkan Perpu karena kegentingan yang memaksa; Perpu kemudian dimintakan persetujuan DPR pada persidangan berikutnya."},
{id:"TWK-1847",q:"Salah satu syarat menjadi presiden menurut Pasal 6 UUD 1945 adalah ....",opts:["warga negara Indonesia sejak kelahirannya","berusia minimal 30 tahun","pernah menjadi anggota DPR","memiliki harta kekayaan tertentu","berdomisili di ibu kota negara"],a:0,ex:"Pasal 6: calon presiden WNI sejak kelahiran, tidak pernah menerima kewarganegaraan lain, tidak berkhianat, mampu jasmani-rohani. Batas usia minimal 40 tahun (kini melalui putusan MK), bukan 30."},
{id:"TWK-1848",q:"Masa jabatan presiden menurut UUD 1945 hasil amandemen adalah ....",opts:["lima tahun dan sesudahnya dapat dipilih kembali satu kali","lima tahun tanpa dapat dipilih kembali","empat tahun dan dapat dipilih berkali-kali","tujuh tahun untuk satu periode","seumur hidup atas ketetapan MPR"],a:0,ex:"Pasal 7 hasil amandemen: presiden memegang jabatan lima tahun, sesudahnya dapat dipilih kembali dalam jabatan yang sama hanya untuk satu kali masa jabatan."},
{id:"TWK-1849",q:"Pelaksana kekuasaan kehakiman menurut UUD 1945 adalah ....",opts:["Mahkamah Agung dan Mahkamah Konstitusi","Mahkamah Agung dan Komisi Yudisial","Mahkamah Konstitusi dan DPR","Kejaksaan Agung dan Kepolisian","Pengadilan Negeri dan Pengadilan Tinggi"],a:0,ex:"Pasal 24: kekuasaan kehakiman dilakukan oleh MA dan badan peradilan di bawahnya serta MK. KY menjaga kehormatan hakim, bukan pelaksana kekuasaan kehakiman."},
{id:"TWK-1850",q:"Pasal 33 UUD 1945 memuat ketentuan mengenai ....",opts:["perekonomian nasional dan kesejahteraan sosial","pertahanan dan keamanan negara","pendidikan dan kebudayaan","hak asasi manusia","agama dan kepercayaan"],a:0,ex:"Pasal 33 mengatur perekonomian disusun sebagai usaha bersama berdasar asas kekeluargaan; pertahanan = Pasal 30, pendidikan = Pasal 31, HAM = Pasal 28A-J, agama = Pasal 29."},
{id:"TWK-1851",q:"DPR memiliki tiga fungsi yaitu ....",opts:["legislasi, anggaran, dan pengawasan","eksekutif, yudikatif, dan legislatif","anggaran, peradilan, dan keamanan","pengawasan, peradilan, dan legislasi","legislasi, eksekutif, dan yudikatif"],a:0,ex:"Tiga fungsi DPR menurut UUD 1945 adalah legislasi (membentuk UU), anggaran (APBN), dan pengawasan. Trias politica adalah pembagian kekuasaan secara umum, bukan fungsi DPR."},
{id:"TWK-1852",q:"Hak DPR meminta keterangan kepada pemerintah tentang kebijakan penting dinamakan ....",opts:["hak interpelasi","hak angket","hak inisiatif","hak imunitas","hak budget"],a:0,ex:"Hak interpelasi = meminta keterangan pemerintah; hak angket = penyelidikan; hak inisiatif = mengusulkan RUU; hak budget = menetapkan APBN."},
{id:"TWK-1853",q:"Hak angket yang dimiliki DPR adalah ....",opts:["hak melakukan penyelidikan terhadap pelaksanaan suatu undang-undang atau kebijakan pemerintah","hak meminta keterangan kepada presiden","hak mengajukan rancangan undang-undang","hak kekebalan hukum bagi anggota dewan","hak menetapkan anggaran pendapatan negara"],a:0,ex:"Hak angket adalah hak penyelidikan DPR; meminta keterangan = interpelasi, mengajukan RUU = inisiatif, kekebalan = imunitas."},
{id:"TWK-1854",q:"Badan Pemeriksa Keuangan (BPK) menurut UUD 1945 bertugas ....",opts:["memeriksa pengelolaan dan tanggung jawab keuangan negara","mengadili perkara korupsi pejabat negara","menyusun anggaran pendapatan dan belanja negara","mengawasi pelaksanaan undang-undang","memberikan pertimbangan hukum kepada presiden"],a:0,ex:"BPK memeriksa keuangan negara (Pasal 23E); mengadili korupsi = pengadilan Tipikor, menyusun APBN = pemerintah-DPR, mengawasi UU = DPR."},
{id:"TWK-1855",q:"Komisi Yudisial menurut UUD 1945 berwenang ....",opts:["menjaga dan menegakkan kehormatan, keluhuran martabat, serta perilaku hakim","mengadili perkara pada tingkat kasasi","menguji undang-undang terhadap UUD 1945","mengangkat dan memberhentikan menteri","menetapkan calon presiden dan wakil presiden"],a:0,ex:"KY menjaga kehormatan hakim dan mengusulkan hakim agung; kasasi = MA, uji UU = MK, angkat menteri = presiden."},
{id:"TWK-1856",q:"Sumpah atau janji presiden dan wakil presiden menurut UUD 1945 tercantum dalam Pasal ....",opts:["9","4","6","7","10"],a:0,ex:"Pasal 9 mengatur sumpah/janji presiden; Pasal 4 kekuasaan pemerintahan, Pasal 6 syarat, Pasal 7 masa jabatan, Pasal 10 kekuasaan tertinggi TNI."},
{id:"TWK-1857",q:"Pasal UUD 1945 yang mengatur presiden sebagai pemegang kekuasaan pemerintahan adalah Pasal ....",opts:["4","6","7","9","20"],a:0,ex:"Pasal 4 ayat (1): presiden memegang kekuasaan pemerintahan menurut UUD; Pasal 20 tentang pembentukan UU oleh DPR."},
{id:"TWK-1858",q:"Menurut UUD 1945, menteri-menteri negara diangkat dan diberhentikan oleh ....",opts:["presiden","DPR","MPR","Mahkamah Agung","partai politik"],a:0,ex:"Pasal 17: presiden dibantu menteri yang diangkat dan diberhentikan presiden; DPR/MPR tidak berwenang mengangkat menteri."},
{id:"TWK-1859",q:"Menurut UUD 1945, pemilihan umum dilaksanakan setiap ....",opts:["lima tahun sekali","empat tahun sekali","tiga tahun sekali","enam tahun sekali","dua tahun sekali"],a:0,ex:"Pasal 22E: pemilu dilaksanakan lima tahun sekali untuk memilih DPR, DPD, presiden-wakil presiden, dan DPRD."},
{id:"TWK-1860",q:"Peserta pemilu anggota DPR dan DPRD menurut UUD 1945 adalah ....",opts:["partai politik","perseorangan","organisasi kemasyarakatan","gabungan partai politik","calon independen"],a:0,ex:"Peserta pemilu anggota DPR/DPRD adalah parpol; perseorangan hanya untuk DPD; calon independen (perseorangan) untuk pilkada/presiden lewat jalur tertentu."},
{id:"TWK-1861",q:"Pengaturan otonomi daerah dalam UUD 1945 terdapat pada Pasal ....",opts:["18","20","22","27","33"],a:0,ex:"Pasal 18 mengatur pembagian daerah dan otonomi; Pasal 20 pembentukan UU, 22 Perpu, 27 hak warga, 33 perekonomian."},
{id:"TWK-1862",q:"Pembagian wilayah NKRI atas daerah provinsi yang otonom menurut UUD 1945 diatur dalam ....",opts:["Pasal 18 UUD 1945","Pasal 20 UUD 1945","Pasal 25A UUD 1945","Pasal 37 UUD 1945","ketetapan MPR"],a:0,ex:"Pasal 18 mengatur NKRI dibagi atas provinsi yang otonom; Pasal 25A wilayah negara, Pasal 37 perubahan UUD."},
{id:"TWK-1863",q:"Hak untuk hidup dan mempertahankan kehidupan serta hak memperoleh pelayanan kesehatan dijamin dalam Pasal .... UUD 1945",opts:["28A","28B","28C","28D","28E"],a:0,ex:"Pasal 28A menjamin hak hidup; 28B keluarga/anak, 28C pendidikan dan HAM, 28D kepastian hukum, 28E agama dan keyakinan."},
{id:"TWK-1864",q:"Pasal 28E UUD 1945 menjamin ....",opts:["kebebasan memeluk agama dan beribadat menurut kepercayaannya","hak atas pekerjaan dan penghidupan yang layak","hak memperoleh pendidikan dasar","hak atas rasa aman dari ancaman","hak mengembangkan diri melalui pendidikan"],a:0,ex:"Pasal 28E: kebebasan agama/keyakinan; pekerjaan = Pasal 27 ayat 2, pendidikan = 28C/31, rasa aman = 28G."},
{id:"TWK-1865",q:"Hak setiap orang untuk mengembangkan diri melalui pendidikan dijamin dalam Pasal .... UUD 1945",opts:["28C","28A","28B","28D","28F"],a:0,ex:"Pasal 28C ayat (1) menjamin hak mengembangkan diri, pendidikan, dan manfaat iptek; 28F tentang informasi."},
{id:"TWK-1866",q:"Ruang lingkup Pasal 31 UUD 1945 meliputi ....",opts:["pendidikan dan kebudayaan","pertahanan dan keamanan","perekonomian nasional","hak asasi manusia","kebebasan beragama"],a:0,ex:"Pasal 31: hak mendapat pendidikan dan kewajiban negara membiayai pendidikan dasar; pertahanan = 30, ekonomi = 33, HAM = 28A-J, agama = 29."},
{id:"TWK-1867",q:"Menurut UUD 1945, anggaran pendidikan dalam APBN dan APBD minimal sebesar ....",opts:["20 persen","15 persen","10 persen","25 persen","30 persen"],a:0,ex:"Pasal 31 ayat (4): negara memprioritaskan anggaran pendidikan sekurang-kurangnya 20% APBN/APBD."},
{id:"TWK-1868",q:"Tugas dan wewenang MPR menurut UUD 1945 antara lain ....",opts:["melantik presiden dan wakil presiden","membentuk undang-undang","mengadili sengketa pemilu","menyusun APBN","mengangkat duta besar"],a:0,ex:"MPR melantik presiden-wapres dan mengubah UUD; membentuk UU = DPR-presiden, sengketa pemilu = MK, APBN = DPR-pemerintah."},
{id:"TWK-1869",q:"Pengertian bela negara adalah ....",opts:["tekad, sikap, dan perilaku warga negara yang dijiwai kecintaannya kepada NKRI","kewajiban mengikuti wajib militer bagi seluruh pemuda","kesediaan menjadi anggota TNI dan Polri","kegiatan latihan baris-berbaris di sekolah","program pemerintah untuk menambah anggaran pertahanan"],a:0,ex:"Bela negara adalah tekad-sikap-perilaku warga yang dijiwai cinta NKRI (UU No. 3/2002); bukan sekadar wajib militer atau latihan baris."},
{id:"TWK-1870",q:"Upaya bela negara diatur secara khusus dalam undang-undang ....",opts:["UU No. 3 Tahun 2002 tentang Pertahanan Negara","UU No. 5 Tahun 2014 tentang ASN","UU No. 23 Tahun 2014 tentang Pemerintahan Daerah","UU No. 12 Tahun 2011 tentang Pembentukan Peraturan Perundang-undangan","UU No. 39 Tahun 1999 tentang Hak Asasi Manusia"],a:0,ex:"UU No. 3/2002 tentang Pertahanan Negara mengatur bela negara dan komponen pertahanan; UU lain mengatur ASN, pemda, pembentukan peraturan, dan HAM."},
{id:"TWK-1871",q:"Berikut ini yang termasuk nilai-nilai dasar bela negara adalah ....",opts:["rela berkorban untuk bangsa dan negara","mementingkan kepentingan pribadi di atas bangsa","bersikap apatis terhadap lingkungan sekitar","menolak segala bentuk perbedaan","mengutamakan kepentingan golongan sendiri"],a:0,ex:"Rela berkorban adalah nilai dasar bela negara; individualisme, apatisme, intoleransi, dan primordialisme justru bertentangan dengannya."},
{id:"TWK-1872",q:"Nilai dasar bela negara yang diwujudkan dengan mendahulukan kepentingan bangsa dan negara di atas kepentingan pribadi adalah ....",opts:["rela berkorban","cinta tanah air","sadar berbangsa dan bernegara","kemampuan awal bela negara","disiplin nasional"],a:0,ex:"Rela berkorban = mendahulukan kepentingan bangsa; cinta tanah air = bangga tanah air, sadar berbangsa = menempatkan persatuan, kemampuan awal = kesiapan fisik-mental."},
{id:"TWK-1873",q:"Sistem pertahanan dan keamanan rakyat semesta sebagai sistem bela negara disingkat ....",opts:["sishankamrata","sishankamnas","hankamrata","siskamling","wanhankamnas"],a:0,ex:"Sishankamrata = Sistem Pertahanan dan Keamanan Rakyat Semesta, sistem pertahanan Indonesia yang melibatkan seluruh komponen bangsa."},
{id:"TWK-1874",q:"Ciri utama sishankamrata adalah ....",opts:["melibatkan seluruh rakyat dan segenap sumber daya nasional","hanya mengandalkan kekuatan TNI semata","bergantung pada bantuan militer negara asing","bersifat ofensif menyerang negara lain","dikelola sepenuhnya oleh kepolisian"],a:0,ex:"Sishankamrata bersifat semesta: melibatkan rakyat dan seluruh sumber daya, bersifat defensif, dan tidak bergantung pada negara asing."},
{id:"TWK-1875",q:"Komponen utama dalam sistem bela negara adalah ....",opts:["TNI","Polri","komponen cadangan","komponen pendukung","satpam"],a:0,ex:"UU No. 3/2002: komponen utama = TNI; Polri komponen pendukung keamanan dalam negeri; komcad dan komponen pendukung melengkapi."},
{id:"TWK-1876",q:"Susunan komponen cadangan pertahanan negara adalah ....",opts:["warga negara yang telah mengikuti pelatihan dasar kemiliteran","seluruh anggota TNI aktif","pegawai negeri sipil di lingkungan pertahanan","anggota organisasi kepemudaan","siswa sekolah menengah atas"],a:0,ex:"Komponen cadangan (Komcad) adalah warga negara terlatih dasar kemiliteran yang dimobilisasi saat dibutuhkan; bukan TNI aktif atau PNS."},
{id:"TWK-1877",q:"Komponen pendukung pertahanan negara meliputi ....",opts:["sumber daya alam, sumber daya manusia, dan sarana prasarana nasional","senjata dan alat utama sistem pertahanan","seluruh prajurit TNI aktif","anggaran belanja pertahanan negara","pangkalan militer di perbatasan"],a:0,ex:"Komponen pendukung = sumber daya nasional (alam, manusia, buatan, sarana) yang dapat digunakan untuk pertahanan; alutsista bagian komponen utama."},
{id:"TWK-1878",q:"Ketahanan nasional pada hakikatnya adalah ....",opts:["kondisi dinamis bangsa berisi keuletan dan ketangguhan menghadapi ancaman","jumlah prajurit dan persenjataan yang dimiliki negara","luas wilayah dan jumlah penduduk suatu negara","tingkat kemakmuran ekonomi masyarakat","kekuatan politik pemerintah yang berkuasa"],a:0,ex:"Ketahanan nasional = kondisi dinamis (keuletan-ketangguhan) bangsa menghadapi ancaman; bukan sekadar jumlah tentara, luas wilayah, atau kemakmuran."},
{id:"TWK-1879",q:"Tiga gatra alamiah pembentuk ketahanan nasional adalah ....",opts:["geografi, demografi, dan kekayaan alam","ideologi, politik, dan ekonomi","sosial, budaya, dan pertahanan","penduduk, wilayah, dan pemerintahan","alam, manusia, dan teknologi"],a:0,ex:"Trigatra (tiga gatra alamiah): geografi, demografi/kependudukan, kekayaan alam; ideologi-politik-ekonomi-sosbud-hankam adalah pancagatra."},
{id:"TWK-1880",q:"Unsur-unsur pancagatra pembentuk ketahanan nasional adalah ....",opts:["ideologi, politik, ekonomi, sosial budaya, dan pertahanan keamanan","geografi, demografi, dan kekayaan alam","wilayah, penduduk, dan pemerintahan","daratan, lautan, dan udara","pertanian, industri, dan perdagangan"],a:0,ex:"Pancagatra (lima gatra sosial): ideologi, politik, ekonomi, sosial budaya, hankam; geografi-demografi-kekayaan alam adalah trigatra."},
{id:"TWK-1881",q:"Contoh ancaman militer terhadap kedaulatan negara adalah ....",opts:["agresi militer oleh negara lain","penyebaran paham radikal di media sosial","krisis moneter yang berkepanjangan","bencana alam gempa bumi","wabah penyakit menular"],a:0,ex:"Agresi militer adalah ancaman militer; paham radikal = nonmiliter ideologi, krisis moneter = nonmiliter ekonomi, bencana/wabah = keselamatan umum."},
{id:"TWK-1882",q:"Pelanggaran wilayah perbatasan oleh kapal perang asing termasuk ancaman ....",opts:["militer","nonmiliter bidang politik","nonmiliter bidang ekonomi","nonmiliter bidang sosial budaya","keselamatan umum"],a:0,ex:"Pelanggaran wilayah oleh kekuatan bersenjata asing adalah ancaman militer; ancaman nonmiliter tidak melibatkan kekuatan senjata."},
{id:"TWK-1883",q:"Penyebaran paham yang bertentangan dengan ideologi bangsa termasuk ancaman ....",opts:["nonmiliter bidang ideologi","militer","nonmiliter bidang ekonomi","nonmiliter bidang politik","keselamatan umum"],a:0,ex:"Perang ideologi/paham termasuk ancaman nonmiliter bidang ideologi; bukan ancaman militer karena tidak menggunakan kekuatan senjata."},
{id:"TWK-1884",q:"Krisis ekonomi yang melumpuhkan perekonomian nasional termasuk ancaman ....",opts:["nonmiliter bidang ekonomi","militer","nonmiliter bidang ideologi","nonmiliter bidang politik","ancaman hibrida"],a:0,ex:"Krisis ekonomi = ancaman nonmiliter bidang ekonomi; hibrida adalah gabungan militer-nonmiliter, bukan krisis ekonomi semata."},
{id:"TWK-1885",q:"Gabungan ancaman yang membentuk ancaman hibrida (hybrid threat) adalah ....",opts:["ancaman militer dan nonmiliter yang terjadi bersamaan","ancaman dari dalam dan luar negeri","ancaman nyata dan ancaman potensial","ancaman tradisional dan modern","ancaman fisik dan ancaman mental"],a:0,ex:"Ancaman hibrida memadukan ancaman militer dan nonmiliter (mis. serangan siber + tekanan militer); bukan sekadar dalam-luar atau nyata-potensial."},
{id:"TWK-1886",q:"Perang proksi (proxy war) dapat didefinisikan sebagai ....",opts:["perang yang menggunakan pihak ketiga untuk mencapai tujuan pihak utama","perang terbuka antar dua negara","perang saudara dalam satu negara","perang melawan penjajah","perang ekonomi antarnegara"],a:0,ex:"Proxy war = konfrontasi lewat pihak ketiga/proksi agar pelaku utama tidak terlibat langsung; berbeda dari perang terbuka, perang saudara, atau perang ekonomi."},
{id:"TWK-1887",q:"Contoh proxy war di era modern adalah ....",opts:["perang informasi melalui media sosial yang didanai pihak asing","pertempuran dua pasukan di medan perang","latihan militer bersama antarnegara","misi perdamaian PBB","perlombaan senjata nuklir"],a:0,ex:"Perang informasi/disinformasi oleh proksi asing adalah bentuk proxy war modern; pertempuran terbuka, latgab, dan misi PBB bukan proxy war."},
{id:"TWK-1888",q:"Seorang pelajar menolak ajakan tawuran dan memilih menyelesaikan masalah dengan dialog. Sikap tersebut mencerminkan bela negara karena ....",opts:["menjaga persatuan dan ketertiban masyarakat","menghindari hukuman dari guru","takut kepada pelaku tawuran","ingin dipuji teman-temannya","menuruti perintah orang tua"],a:0,ex:"Menolak kekerasan dan menjaga ketertiban adalah wujud bela negara nonfisik; motif takut, cari pujian, atau sekadar patuh bukan esensi bela negara."},
{id:"TWK-1889",q:"Membeli dan menggunakan produk dalam negeri merupakan wujud bela negara karena ....",opts:["memperkuat ketahanan ekonomi nasional","harganya selalu lebih murah","kualitasnya pasti lebih baik","diwajibkan oleh undang-undang","agar terlihat nasionalis"],a:0,ex:"Cinta produk dalam negeri memperkuat ekonomi nasional (ketahanan ekonomi); bukan soal harga, kualitas mutlak, kewajiban hukum, atau pencitraan."},
{id:"TWK-1890",q:"Upacara bendera setiap hari Senin di sekolah termasuk pengamalan bela negara dalam aspek ....",opts:["mental, disiplin, dan nasionalisme","keterampilan baris-berbaris","kewajiban administratif sekolah","kegiatan ekstrakurikuler","persiapan menjadi TNI"],a:0,ex:"Upacara bendera menanamkan disiplin, nasionalisme, dan penghormatan simbol negara; bukan sekadar baris-berbaris atau persiapan militer."},
{id:"TWK-1891",q:"Kemampuan awal bela negara bagi warga sipil dapat dibentuk melalui ....",opts:["pendidikan kewarganegaraan dan pelatihan dasar","pendidikan militer penuh selama dua tahun","keanggotaan organisasi politik","kursus bela diri profesional","penataran ideologi tertutup"],a:0,ex:"Kemampuan awal bela negara dibentuk lewat pendidikan kewarganegaraan dan latihan dasar; bukan pendidikan militer penuh atau kursus bela diri."},
{id:"TWK-1892",q:"Sikap selektif terhadap budaya asing yang masuk merupakan wujud bela negara karena ....",opts:["melindungi jati diri dan kepribadian bangsa","menolak seluruh kemajuan zaman","membenci bangsa lain","menutup diri dari dunia luar","menjaga kemurnian ras bangsa"],a:0,ex:"Selektif = menyaring budaya asing agar jati diri bangsa terjaga, bukan menolak kemajuan, membenci bangsa lain, atau menutup diri total."},
{id:"TWK-1893",q:"TNI sebagai komponen utama dalam sistem bela negara memiliki tugas pokok ....",opts:["menegakkan kedaulatan negara dan mempertahankan keutuhan wilayah","menjaga keamanan dan ketertiban masyarakat","menegakkan hukum dan keadilan","mengatur lalu lintas dan keramaian","melindungi pejabat negara"],a:0,ex:"Tugas pokok TNI (UU No. 34/2004): menegakkan kedaulatan dan keutuhan wilayah; kamtibmas dan penegakan hukum adalah tugas Polri."},
{id:"TWK-1894",q:"Peran serta warga negara dalam upaya bela negara yang bersifat sukarela dan terorganisir diwadahi melalui ....",opts:["komponen cadangan dan komponen pendukung","wajib militer bagi seluruh warga","keanggotaan TNI aktif","dinas kepolisian khusus","organisasi masyarakat"],a:0,ex:"UU No. 23/2019 (PSDN): peran warga diwadahi lewat Komcad dan komponen pendukung; Indonesia tidak menerapkan wajib militer."},
{id:"TWK-1895",q:"Ancaman siber terhadap sistem informasi nasional termasuk ancaman ....",opts:["nonmiliter","militer","hibrida","agresi","spionase bersenjata"],a:0,ex:"Serangan siber umumnya ancaman nonmiliter (teknologi-informasi); menjadi hibrida bila dipadukan dengan ancaman militer."},
{id:"TWK-1896",q:"Spionase yang dilakukan agen negara asing termasuk ancaman ....",opts:["militer","nonmiliter bidang ekonomi","nonmiliter bidang politik","keselamatan umum","ancaman potensial"],a:0,ex:"Spionase/mata-mata dikategorikan ancaman militer dalam doktrin pertahanan; bukan ancaman ekonomi, politik, atau keselamatan umum."},
{id:"TWK-1897",q:"Pemberontakan bersenjata terhadap pemerintah yang sah termasuk ancaman ....",opts:["militer","nonmiliter bidang politik","nonmiliter bidang ideologi","keselamatan umum","ancaman nirbentuk"],a:0,ex:"Pemberontakan bersenjata menggunakan kekuatan senjata sehingga termasuk ancaman militer; konflik politik tanpa senjata = nonmiliter."},
{id:"TWK-1898",q:"Peredaran narkoba yang merusak generasi muda bangsa termasuk ancaman ....",opts:["nonmiliter","militer","hibrida","agresi militer","pelanggaran wilayah"],a:0,ex:"Narkoba adalah ancaman nonmiliter (sosial kemasyarakatan); tidak melibatkan kekuatan bersenjata sehingga bukan ancaman militer."},
{id:"TWK-1899",q:"Menjaga kerukunan antarumat beragama merupakan wujud bela negara dalam aspek ....",opts:["sosial budaya","pertahanan fisik","ekonomi kerakyatan","politik praktis","teknologi informasi"],a:0,ex:"Kerukunan umat beragama memperkuat ketahanan sosial budaya; bukan aspek pertahanan fisik, ekonomi, politik praktis, atau teknologi."},
{id:"TWK-1900",q:"Tujuan utama bela negara adalah ....",opts:["menjamin kelangsungan hidup bangsa dan negara","memperbanyak jumlah tentara","menambah anggaran pertahanan","menakuti negara tetangga","memenangkan perlombaan senjata"],a:0,ex:"Bela negara bertujuan menjamin kelangsungan hidup bangsa-negara dari segala ancaman; bukan perlombaan senjata atau unjuk kekuatan."},
{id:"TWK-1901",q:"Sikap rela berkorban dalam bela negara diwujudkan dengan ....",opts:["mendahulukan kepentingan bangsa dan negara di atas kepentingan pribadi atau golongan","mengorbankan waktu bermain untuk belajar","menyerahkan seluruh harta kepada negara","mengikuti setiap perintah atasan tanpa kritik","menghindari segala bentuk perbedaan pendapat"],a:0,ex:"Rela berkorban = mendahulukan kepentingan bangsa-negara; bukan mengorbankan harta total, patuh buta, atau menghindari perbedaan."},
{id:"TWK-1902",q:"VOC didirikan pada tahun ....",opts:["1602","1596","1619","1799","1800"],a:0,ex:"VOC (Vereenigde Oostindische Compagnie) didirikan 20 Maret 1602; 1596 kedatangan Cornelis de Houtman, 1619 JP Coen membangun Batavia, 1799 VOC bubar."},
{id:"TWK-1903",q:"Tujuan utama VOC didirikan adalah ....",opts:["menguasai perdagangan rempah-rempah di Nusantara","menyebarkan agama di Asia Tenggara","membangun sekolah-sekolah di Hindia Belanda","menjalin persahabatan dengan kerajaan lokal","melakukan penelitian ilmiah di daerah tropis"],a:0,ex:"VOC adalah kongsi dagang untuk monopoli rempah; bukan misi agama, pendidikan, persahabatan, atau penelitian."},
{id:"TWK-1904",q:"VOC dinyatakan bangkrut dan dibubarkan pada tahun ....",opts:["1799","1800","1795","1811","1816"],a:0,ex:"VOC bubar 31 Desember 1799 karena korupsi, perang, dan utang; 1800 awal pemerintahan Hindia Belanda, 1811 Inggris masuk, 1816 Belanda kembali."},
{id:"TWK-1905",q:"Sistem tanam paksa pada masa penjajahan Belanda diberlakukan oleh ....",opts:["Gubernur Jenderal Van den Bosch","Gubernur Jenderal Daendels","Raja Willem V","Thomas Stamford Raffles","Gubernur Jenderal Van der Capellen"],a:0,ex:"Cultuurstelsel (1830) oleh Van den Bosch; Daendels membangun Jalan Anyer-Panarukan, Raffles berkuasa masa Inggris 1811-1816."},
{id:"TWK-1906",q:"Organisasi pergerakan nasional Budi Utomo didirikan pada tanggal ....",opts:["20 Mei 1908","28 Oktober 1928","1 Juni 1945","17 Agustus 1945","2 Mei 1926"],a:0,ex:"Budi Utomo berdiri 20 Mei 1908 (diperingati Hari Kebangkitan Nasional); 1928 Sumpah Pemuda, 1945 kemerdekaan."},
{id:"TWK-1907",q:"Ketua organisasi pergerakan Budi Utomo adalah ....",opts:["dr. Soetomo","Ki Hajar Dewantara","H.O.S. Tjokroaminoto","Haji Agus Salim","Mr. Sartono"],a:0,ex:"Budi Utomo diketuai dr. Soetomo atas gagasan dr. Wahidin Sudirohusodo; tokoh lain memimpin organisasi pergerakan berbeda."},
{id:"TWK-1908",q:"Tiga Serangkai tokoh pergerakan yang mendirikan Indische Partij adalah ....",opts:["Douwes Dekker, Tjipto Mangunkusumo, Ki Hajar Dewantara","Soekarno, Hatta, Syahrir","Wahidin, Soetomo, Cipto","Tjokroaminoto, Agus Salim, Muis","Yamin, Soepomo, Soebarjo"],a:0,ex:"Indische Partij (1912) didirikan Tiga Serangkai: Douwes Dekker, Tjipto, Ki Hajar Dewantara. Kelompok lain berasal dari era/organisasi berbeda."},
{id:"TWK-1909",q:"Pengikraran Sumpah Pemuda terjadi pada tanggal ....",opts:["28 Oktober 1928","20 Mei 1908","1 Juni 1945","17 Agustus 1945","10 November 1945"],a:0,ex:"Kongres Pemuda II menghasilkan Sumpah Pemuda 28 Oktober 1928; 1908 Budi Utomo, 1945 kemerdekaan."},
{id:"TWK-1910",q:"Isi ikrar Sumpah Pemuda yang ketiga adalah ....",opts:["menjunjung bahasa persatuan, bahasa Indonesia","bertumpah darah yang satu, tanah Indonesia","berbangsa yang satu, bangsa Indonesia","menjunjung tinggi persatuan pemuda","setia kepada tanah air Indonesia"],a:0,ex:"Ikrar ketiga: menjunjung bahasa persatuan bahasa Indonesia; ikrar pertama tanah air, kedua bangsa Indonesia."},
{id:"TWK-1911",q:"Kongres Pemuda II yang menghasilkan Sumpah Pemuda diketuai oleh ....",opts:["Soegondo Djojopoespito","Mohammad Yamin","Soenario","Djoko Marsaid","Amir Syarifuddin"],a:0,ex:"Kongres Pemuda II (1928) diketuai Soegondo Djojopoespito; Yamin menjadi sekretaris dan perumus ikrar."},
{id:"TWK-1912",q:"Partai pergerakan PNI didirikan oleh Ir. Soekarno pada tahun ....",opts:["1927","1928","1926","1931","1912"],a:0,ex:"PNI didirikan 4 Juli 1927 di Bandung; 1928 Sumpah Pemuda, 1912 Indische Partij dan Sarekat Islam."},
{id:"TWK-1913",q:"Peristiwa Rengasdengklok menjelang proklamasi kemerdekaan terjadi karena ....",opts:["golongan muda mendesak Soekarno-Hatta segera memproklamasikan kemerdekaan","Jepang melarang kegiatan politik kaum pergerakan","Belanda melancarkan agresi militer","terjadi perbedaan pendapat tentang dasar negara","para pemuda ingin merebut senjata Jepang"],a:0,ex:"Golongan muda (Wikana dkk.) membawa Soekarno-Hatta ke Rengasdengklok 16 Agustus 1945 agar proklamasi tidak ditunda menunggu sidang PPKI."},
{id:"TWK-1914",q:"Teks proklamasi kemerdekaan Indonesia diketik oleh ....",opts:["Sayuti Melik","B.M. Diah","Soekarni","Ahmad Soebardjo","Sukarni"],a:0,ex:"Sayuti Melik mengetik teks proklamasi di rumah Laksamana Maeda; Soekarno-Hatta menyusun konsepnya."},
{id:"TWK-1915",q:"Proklamasi kemerdekaan Indonesia dibacakan di ....",opts:["Jalan Pegangsaan Timur No. 56 Jakarta","Lapangan Ikada Jakarta","Gedung Merdeka Bandung","Jalan Imam Bonjol No. 1","Istana Merdeka Jakarta"],a:0,ex:"Proklamasi dibacakan di kediaman Soekarno, Jl. Pegangsaan Timur 56, pukul 10.00 WIB 17 Agustus 1945; Lapangan Ikada rencana awal yang batal."},
{id:"TWK-1916",q:"Kalimat pertama teks proklamasi kemerdekaan adalah ....",opts:["Kami bangsa Indonesia dengan ini menjatakan kemerdekaan Indonesia","Atas berkat rahmat Allah Yang Maha Kuasa","Bahwa sesungguhnya kemerdekaan itu ialah hak segala bangsa","Proklamasi kemerdekaan bangsa Indonesia","Merdeka atau mati bagi bangsa Indonesia"],a:0,ex:"Kalimat pertama teks proklamasi adalah pernyataan kemerdekaan; kalimat kedua tentang pemindahan kekuasaan. Pilihan lain dari Pembukaan UUD 1945."},
{id:"TWK-1917",q:"Pertempuran Surabaya 10 November 1945 dalam masa revolusi fisik dipicu oleh ....",opts:["tewasnya Brigjen Mallaby dan ultimatum Inggris","pendaratan tentara Jepang di Surabaya","perebutan senjata dari Belanda","pembentukan pemerintahan RIS","penolakan hasil Perjanjian Renville"],a:0,ex:"Insiden Jembatan Merah (tewasnya Mallaby 30 Okt) dan ultimatum Inggris memicu pertempuran 10 November yang diperingati Hari Pahlawan."},
{id:"TWK-1918",q:"Tokoh yang membakar semangat arek-arek Surabaya dalam pertempuran mempertahankan kemerdekaan melalui pidato radio adalah ....",opts:["Bung Tomo","Gubernur Suryo","Mayjen Soengkono","Bung Karno","Jenderal Sudirman"],a:0,ex:"Sutomo (Bung Tomo) berorasi lewat radio membakar perlawanan Surabaya; Gubernur Suryo pemimpin pemerintahan setempat."},
{id:"TWK-1919",q:"Peristiwa Bandung Lautan Api dalam mempertahankan kemerdekaan terjadi pada ....",opts:["24 Maret 1946","10 November 1945","19 Desember 1948","21 Juli 1947","17 Agustus 1945"],a:0,ex:"Bandung Lautan Api 24 Maret 1946: rakyat membakar Bandung Selatan agar tidak dikuasai Inggris; dipimpin Kol. A.H. Nasution."},
{id:"TWK-1920",q:"Perang Puputan Margarana dalam mempertahankan kemerdekaan dipimpin oleh ....",opts:["I Gusti Ngurah Rai","I Gusti Ketut Pudja","Rai Mantra","Anak Agung Gde Agung","Tjokorda Gde Raka"],a:0,ex:"Ngurah Rai memimpin Ciung Wanara puputan 20 November 1946 melawan Belanda di Bali; diperingati Hari Puputan Margarana."},
{id:"TWK-1921",q:"Pelancaran Agresi Militer Belanda I terjadi pada tanggal ....",opts:["21 Juli 1947","19 Desember 1948","27 Desember 1949","25 Maret 1947","17 Januari 1948"],a:0,ex:"Agresi I (Operatie Product) 21 Juli 1947; Agresi II 19 Desember 1948; 27 Desember 1949 penyerahan kedaulatan."},
{id:"TWK-1922",q:"Agresi Militer Belanda II dimulai dengan serangan ke Yogyakarta pada tanggal ....",opts:["19 Desember 1948","21 Juli 1947","10 November 1945","24 Maret 1946","7 Mei 1949"],a:0,ex:"Agresi II (Operatie Kraai) 19 Desember 1948 menyerbu Yogyakarta dan menangkap Soekarno-Hatta; memicu pembentukan PDRI."},
{id:"TWK-1923",q:"PDRI dibentuk sebagai akibat agresi militer Belanda II dipimpin oleh ....",opts:["Mr. Sjafruddin Prawiranegara","Mr. Assaat","Jenderal Sudirman","Sutan Syahrir","Mr. Sartono"],a:0,ex:"PDRI (22 Des 1948, Bukittinggi) dipimpin Sjafruddin Prawiranegara agar RI tetap eksis saat pimpinan ditawan Belanda."},
{id:"TWK-1924",q:"Perjanjian Linggarjati ditandatangani pada tanggal ....",opts:["25 Maret 1947","15 November 1946","17 Januari 1948","7 Mei 1949","2 November 1949"],a:0,ex:"Linggarjati dirundingkan November 1946 dan ditandatangani 25 Maret 1947; Renville 17 Jan 1948, Roem-Royen 7 Mei 1949."},
{id:"TWK-1925",q:"Isi pokok Perjanjian Renville adalah ....",opts:["pengakuan wilayah RI sesuai garis demarkasi Van Mook","Belanda mengakui kedaulatan penuh Indonesia","pembentukan negara RIS","gencatan senjata tanpa syarat","penarikan seluruh tentara Belanda"],a:0,ex:"Renville (17 Jan 1948) menetapkan garis Van Mook sehingga wilayah RI menyusut; kedaulatan penuh baru diakui pasca KMB."},
{id:"TWK-1926",q:"Hasil Konferensi Meja Bundar (KMB) adalah ....",opts:["Belanda mengakui kedaulatan Indonesia","Indonesia menjadi negara bagian Belanda","Belanda menarik seluruh klaim Irian Barat","terbentuknya negara kesatuan segera","dibubarkannya TNI"],a:0,ex:"KMB (1949) menghasilkan pengakuan kedaulatan 27 Des 1949 dan pembentukan RIS; Irian Barat ditunda setahun kemudian."},
{id:"TWK-1927",q:"KMB diselenggarakan pada tanggal ....",opts:["23 Agustus - 2 November 1949","17 Januari - 17 Februari 1948","7 Mei - 7 Juni 1949","25 Maret - 25 April 1947","15 - 25 November 1946"],a:0,ex:"KMB berlangsung 23 Agustus-2 November 1949 di Den Haag; delegasi RI dipimpin Drs. Mohammad Hatta."},
{id:"TWK-1928",q:"Masa pendudukan Jepang di Indonesia berlangsung tahun ....",opts:["1942-1945","1941-1944","1943-1946","1940-1943","1945-1948"],a:0,ex:"Jepang mendarat 1942 (Tarakan, lalu Jawa Maret 1942) dan menyerah Agustus 1945; 1941 Pearl Harbor, 1946 Inggris-Belanda masuk."},
{id:"TWK-1929",q:"Organisasi bentukan Jepang yang bertujuan menghimpun kekuatan rakyat Indonesia adalah ....",opts:["Putera","PETA","Fujinkai","Seinendan","Keibodan"],a:0,ex:"Putera (Pusat Tenaga Rakyat, 1943) menghimpun kekuatan rakyat; PETA tentara sukarela, Fujinkai wanita, Seinendan pemuda, Keibodan pembantu polisi."},
{id:"TWK-1930",q:"Janji kemerdekaan Jepang disampaikan Perdana Menteri Koiso pada tanggal ....",opts:["7 September 1944","29 April 1945","1 Juni 1945","17 Agustus 1945","7 September 1945"],a:0,ex:"Janji Koiso 7 September 1944 menjadi dasar pembentukan BPUPKI (29 April 1945); kemerdekaan diproklamasikan 17 Agustus 1945."},
{id:"TWK-1931",q:"Gerakan 30 September 1965 pada masa Orde Lama yang menewaskan para perwira TNI AD menjadi awal berakhirnya ....",opts:["Orde Lama","Orde Baru","masa revolusi fisik","masa demokrasi liberal","era reformasi"],a:0,ex:"G30S 1965 mengakhiri Orde Lama dan membuka Orde Baru lewat Supersemar; demokrasi liberal 1950-1959, reformasi 1998."},
{id:"TWK-1932",q:"Surat Perintah 11 Maret 1966 menandai peralihan kekuasaan dari Orde Lama ke ....",opts:["Orde Baru","era reformasi","masa RIS","demokrasi terpimpin","pemerintahan darurat"],a:0,ex:"Supersemar memberi Soeharto wewenang memulihkan keamanan, menandai lahirnya Orde Baru; reformasi baru 1998."},
{id:"TWK-1933",q:"Reformasi 1998 ditandai dengan peristiwa ....",opts:["pengunduran diri Presiden Soeharto pada 21 Mei 1998","terbitnya Dekrit Presiden 5 Juli 1959","dikeluarkannya Supersemar","pembubaran Konstituante","penandatanganan Perjanjian Renville"],a:0,ex:"Soeharto mundur 21 Mei 1998 digantikan B.J. Habibie sebagai puncak reformasi; peristiwa lain dari era berbeda."},
{id:"TWK-1934",q:"Salah satu dari enam agenda reformasi tahun 1998 adalah ....",opts:["pemberantasan korupsi, kolusi, dan nepotisme","penghapusan seluruh partai politik","pembubaran lembaga kepresidenan","pengembalian UUD 1945 naskah asli","penutupan hubungan luar negeri"],a:0,ex:"Enam agenda reformasi: suksesi kepemimpinan, pemberantasan KKN, amandemen UUD, penghapusan dwifungsi ABRI, penegakan HAM, otonomi daerah."},
{id:"TWK-1935",q:"Kitab Sutasoma yang memuat frasa Bhinneka Tunggal Ika dikarang oleh ....",opts:["Mpu Tantular","Mpu Prapanca","Mpu Kanwa","Empu Sedah","Mpu Panuluh"],a:0,ex:"Mpu Tantular mengarang Sutasoma era Majapahit; Mpu Prapanca mengarang Negarakertagama, Empu Sedah-Panuluh Bharatayudha."},
{id:"TWK-1936",q:"Unsur wadah dalam Wawasan Nusantara meliputi ....",opts:["wilayah beserta seluruh isinya","cita-cita dan tujuan nasional","tingkah laku lahiriah dan batiniah","ideologi dan politik negara","ekonomi dan pertahanan"],a:0,ex:"Wawasan Nusantara: wadah (wilayah + isinya), isi (cita-cita/tujuan), tata laku (lahir-batin). Ideologi-politik-ekonomi bagian astagatra."},
{id:"TWK-1937",q:"Astagatra dalam Wawasan Nusantara terdiri atas ....",opts:["trigatra dan pancagatra","dwigatra dan pancagatra","ekagatra dan saptagatra","caturgatra dan trigatra","pancagatra dan dwigatra"],a:0,ex:"Astagatra = delapan gatra: trigatra (geografi, demografi, kekayaan alam) + pancagatra (ideologi, politik, ekonomi, sosbud, hankam)."},
{id:"TWK-1938",q:"Pencetusan Deklarasi Djuanda terjadi pada tanggal ....",opts:["13 Desember 1957","17 Agustus 1945","28 Oktober 1928","20 Mei 1908","8 Agustus 1967"],a:0,ex:"Deklarasi Djuanda 13 Desember 1957 oleh PM Djuanda Kartawidjaja tentang wilayah perairan Indonesia; 1967 deklarasi Bangkok ASEAN."},
{id:"TWK-1939",q:"Substansi utama Deklarasi Djuanda adalah ....",opts:["laut-laut Indonesia sebagai satu kesatuan wilayah nusantara","Indonesia menganut politik bebas aktif","pembentukan ASEAN","pengakuan kedaulatan oleh Belanda","penetapan ibu kota negara"],a:0,ex:"Deklarasi Djuanda menegaskan perairan antarpulau sebagai wilayah nasional (negara kepulauan); politik bebas aktif = Hatta, ASEAN = 1967."},
{id:"TWK-1940",q:"Lebar laut teritorial Indonesia menurut Deklarasi Djuanda adalah ....",opts:["12 mil laut","3 mil laut","6 mil laut","200 mil laut","24 mil laut"],a:0,ex:"Deklarasi Djuanda menetapkan 12 mil dari garis dasar; 3 mil aturan lama kolonial, 200 mil ZEE (UNCLOS 1982)."},
{id:"TWK-1941",q:"Negara yang memiliki perbatasan darat langsung dengan Indonesia adalah ....",opts:["Malaysia, Papua Nugini, dan Timor Leste","Singapura, Filipina, dan Australia","Thailand, Vietnam, dan Kamboja","Brunei, Laos, dan Myanmar","India, Sri Lanka, dan Maladewa"],a:0,ex:"Perbatasan darat RI: Malaysia (Kalimantan), PNG (Papua), Timor Leste (Timor); negara lain hanya berbatasan laut."},
{id:"TWK-1942",q:"Dua pulau terluar yang menjadi sengketa Indonesia-Malaysia hingga diputus tahun 2002 adalah ....",opts:["Sipadan dan Ligitan","Natuna dan Anambas","Miangas dan Marampit","Rote dan Sabu","Weh dan Breueh"],a:0,ex:"Sipadan-Ligitan diputus Mahkamah Internasional 2002 untuk Malaysia; pulau lain tidak bersengketa atau sengketa berbeda."},
{id:"TWK-1943",q:"ASEAN didirikan pada tanggal ....",opts:["8 Agustus 1967","13 Desember 1957","28 Oktober 1928","17 Agustus 1945","31 Juli 1961"],a:0,ex:"ASEAN berdiri 8 Agustus 1967 lewat Deklarasi Bangkok; 1957 Deklarasi Djuanda, 1961 ASA/MAPHILINDO cikal bakal."},
{id:"TWK-1944",q:"Deklarasi Bangkok yang menandai berdirinya ASEAN ditandatangani oleh ....",opts:["lima menteri luar negeri negara pendiri","para kepala negara Asia Tenggara","duta besar negara-negara Asia","panglima angkatan bersenjata","utusan PBB"],a:0,ex:"Deklarasi Bangkok ditandatangani 5 menlu: Adam Malik (RI), Tun Abdul Razak (Malaysia), Thanat Khoman (Thailand), Narciso Ramos (Filipina), S. Rajaratnam (Singapura)."},
{id:"TWK-1945",q:"Tujuan utama pembentukan ASEAN adalah ....",opts:["mempercepat pertumbuhan ekonomi dan stabilitas kawasan","membentuk pakta pertahanan militer","menyatukan seluruh Asia Tenggara menjadi satu negara","menghapus seluruh batas negara anggota","menandingi kekuatan PBB"],a:0,ex:"ASEAN bertujuan kerja sama ekonomi, sosial, budaya, dan stabilitas; bukan pakta militer (seperti SEATO) atau penyatuan negara."},
{id:"TWK-1946",q:"Ibu Kota Nusantara (IKN) ditetapkan melalui ....",opts:["UU No. 3 Tahun 2022","UU No. 23 Tahun 2014","Perpres No. 54 Tahun 2020","TAP MPR No. 1 Tahun 2022","Kepres No. 10 Tahun 2021"],a:0,ex:"UU No. 3/2022 tentang Ibu Kota Negara menetapkan Nusantara di Kalimantan Timur; UU 23/2014 tentang Pemerintahan Daerah."},
{id:"TWK-1947",q:"Integrasi nasional dalam bingkai NKRI dapat diwujudkan melalui ....",opts:["penghormatan terhadap keberagaman dan penegakan keadilan","penyeragaman seluruh budaya daerah","pembatasan kebebasan berpendapat","penghapusan otonomi daerah","dominasi satu kelompok atas lainnya"],a:0,ex:"Integrasi nasional terwujud lewat toleransi keberagaman dan keadilan; penyeragaman, pembatasan kebebasan, dan dominasi justru menghambat."},
{id:"TWK-1948",q:"Faktor penghambat integrasi nasional dalam NKRI adalah ....",opts:["ketidakmerataan pembangunan antar daerah","keberagaman suku dan budaya","sistem otonomi daerah","kebebasan pers yang bertanggung jawab","partisipasi masyarakat dalam pemilu"],a:0,ex:"Ketidakmerataan pembangunan menimbulkan kecemburuan daerah; keberagaman, otonomi, pers bebas, dan partisipasi justru perekat bila dikelola baik."},
{id:"TWK-1949",q:"Pulau-pulau terluar Indonesia berfungsi sebagai ....",opts:["titik dasar penentuan batas wilayah negara","kawasan wisata prioritas","pusat pemerintahan daerah","daerah penyangga ibu kota","kawasan industri khusus"],a:0,ex:"Pulau terluar menjadi titik dasar (basepoint) garis pangkal kepulauan penentu batas wilayah; fungsi wisata/industri bersifat tambahan."},
{id:"TWK-1950",q:"Sikap yang mencerminkan wawasan kebangsaan dalam kehidupan sehari-hari adalah ....",opts:["menghargai perbedaan suku, agama, dan budaya","bergaul hanya dengan sesama suku","mengutamakan kepentingan kelompok sendiri","menolak musyawarah dalam mengambil keputusan","acuh terhadap persoalan bangsa"],a:0,ex:"Wawasan kebangsaan = cara pandang mengutamakan persatuan dalam keberagaman; eksklusivisme suku, primordialisme, dan apatisme bertentangan dengannya."},
{id:"TWK-1951",q:"NKRI menganut bentuk negara ....",opts:["kesatuan yang berbentuk republik","serikat yang berbentuk kerajaan","kesatuan yang berbentuk monarki","serikat yang berbentuk republik","konfederasi negara-negara bagian"],a:0,ex:"Indonesia adalah negara kesatuan berbentuk republik (Pasal 1 UUD 1945); bukan negara serikat/federal, monarki, atau konfederasi."},
{id:"TWK-1952",q:"Ciri negara kesatuan dalam NKRI adalah ....",opts:["kedaulatan berada di tangan pemerintah pusat","setiap daerah memiliki konstitusi sendiri","kepala negara dipilih oleh parlemen daerah","daerah bebas membuat angkatan bersenjata","pemerintah pusat hanya mengurus luar negeri"],a:0,ex:"Negara kesatuan: kedaulatan tunggal di pemerintah pusat, satu konstitusi; daerah otonom bukan berdaulat. Pilihan lain ciri negara federal."},
{id:"TWK-1953",q:"Lagu kebangsaan Indonesia Raya yang menjadi simbol NKRI diciptakan oleh ....",opts:["W.R. Supratman","Ismail Marzuki","C. Simanjuntak","Kusbini","H. Mutahar"],a:0,ex:"Indonesia Raya karya W.R. Supratman (1928); Ismail Marzuki: Halo-Halo Bandung, H. Mutahar: Hari Merdeka dan Hymne Syukur."},
{id:"TWK-1954",q:"Fungsi bahasa Indonesia sebagai bahasa persatuan dalam NKRI adalah ....",opts:["alat pemersatu berbagai suku bangsa","bahasa pengantar ilmu pengetahuan dunia","pengganti seluruh bahasa daerah","bahasa resmi perdagangan internasional","alat komunikasi suku tertentu"],a:0,ex:"Bahasa Indonesia pemersatu bangsa (Sumpah Pemuda); bukan menggantikan bahasa daerah atau menjadi bahasa internasional."},
{id:"TWK-1955",q:"Prinsip politik luar negeri NKRI yang bebas aktif dicetuskan oleh ....",opts:["Mohammad Hatta","Soekarno","Sutan Syahrir","Adam Malik","Ali Alatas"],a:0,ex:"Bebas aktif dicetuskan Hatta (1948); Soekarno: Nasakom, Adam Malik: menlu pendiri ASEAN, Ali Alatas: menlu Orde Baru."},
{id:"TWK-1956",q:"Hasil Konferensi Asia Afrika 1955 yang dikenal sebagai Deklarasi Bandung adalah ....",opts:["Dasasila Bandung","Deklarasi Djuanda","Piagam Jakarta","Deklarasi Bangkok","Trikora"],a:0,ex:"KAA 1955 menghasilkan Dasasila Bandung (sepuluh prinsip hubungan antarnegara); Deklarasi Djuanda 1957, Bangkok 1967 ASEAN."},
{id:"TWK-1957",q:"Indonesia sebagai negara NKRI ikut mendirikan Gerakan Non-Blok pada tahun ....",opts:["1961","1955","1967","1945","1973"],a:0,ex:"GNB berdiri 1961 di Beograd; 1955 KAA Bandung, 1967 ASEAN, 1973 KTT Non-Blok di Aljazair."},
{id:"TWK-1958",q:"Tujuan politik luar negeri NKRI yang bebas aktif adalah ....",opts:["menjaga perdamaian dunia dan keadilan sosial","memihak blok Barat melawan blok Timur","menghindari hubungan dengan negara lain","menjadi anggota tetap Dewan Keamanan PBB","memimpin seluruh negara Asia"],a:0,ex:"Bebas aktif = bebas menentukan sikap, aktif menjaga perdamaian (Pembukaan UUD 1945); bukan memihak blok atau isolasi."},
{id:"TWK-1959",q:"Contoh sikap nasionalisme dalam menjaga keutuhan NKRI di era globalisasi adalah ....",opts:["menggunakan produk dalam negeri","menolak seluruh teknologi asing","bergaul hanya dengan sebangsa","menutup diri dari dunia luar","mengklaim budaya negara lain"],a:0,ex:"Nasionalisme modern: cinta produk dalam negeri, selektif budaya asing; bukan menolak teknologi, eksklusif, atau klaim budaya."},
{id:"TWK-1960",q:"Disintegrasi bangsa dalam NKRI dapat dicegah dengan ....",opts:["pemerataan pembangunan dan penegakan hukum yang adil","penyeragaman seluruh kebudayaan daerah","pembatasan kebebasan berpendapat","penghapusan pemilihan umum","sentralisasi seluruh kekuasaan"],a:0,ex:"Pemerataan dan keadilan mencegah disintegrasi; penyeragaman, pembatasan kebebasan, dan sentralisasi justru memicu perpecahan."},
{id:"TWK-1961",q:"Modal utama menjaga keutuhan NKRI adalah ....",opts:["persatuan dan kesatuan seluruh rakyat","kekuatan militer yang besar","kekayaan sumber daya alam","bantuan negara asing","jumlah penduduk yang banyak"],a:0,ex:"Persatuan-kesatuan adalah modal utama keutuhan NKRI; militer, SDA, dan penduduk adalah pendukung, bukan modal utama."},
{id:"TWK-1962",q:"Wawasan Nusantara berfungsi sebagai ....",opts:["pedoman dan rambu-rambu perjuangan bangsa Indonesia","aturan hukum tertulis yang mengikat","ideologi pengganti Pancasila","program pembangunan lima tahun","doktrin militer semata"],a:0,ex:"Wawasan Nusantara = cara pandang dan pedoman perjuangan bangsa; bukan peraturan hukum, ideologi pengganti, atau doktrin militer."},
{id:"TWK-1963",q:"Kedudukan Wawasan Nusantara dalam penyelenggaraan negara adalah ....",opts:["sebagai visi nasional bangsa Indonesia","sebagai undang-undang dasar","sebagai peraturan pemerintah","sebagai keputusan presiden","sebagai ketetapan MPR"],a:0,ex:"Wawasan Nusantara berkedudukan sebagai visi nasional; bukan peraturan perundang-undangan formal seperti UU atau tap MPR."},
{id:"TWK-1964",q:"Pulau Kalimantan memiliki perbatasan darat dengan negara ....",opts:["Malaysia","Singapura","Filipina","Thailand","Vietnam"],a:0,ex:"Kalimantan berbatasan darat dengan Malaysia (Sabah-Sarawak); Singapura, Filipina, Thailand, Vietnam hanya berbatasan laut."},
{id:"TWK-1965",q:"Pulau Papua memiliki perbatasan darat dengan negara ....",opts:["Papua Nugini","Australia","Timor Leste","Malaysia","Filipina"],a:0,ex:"Papua berbatasan darat dengan Papua Nugini; Australia dan Timor Leste berbatasan laut/darat di wilayah berbeda."},
{id:"TWK-1966",q:"Selat Malaka sebagai alur laut strategis di kawasan perbatasan Indonesia berbatasan langsung dengan ....",opts:["Malaysia dan Singapura","Thailand dan Vietnam","Filipina dan Malaysia","Australia dan Timor Leste","India dan Sri Lanka"],a:0,ex:"Selat Malaka diapit Sumatra (RI), Malaysia, dan Singapura; selat lain berbatasan dengan negara berbeda."},
{id:"TWK-1967",q:"Zona Ekonomi Eksklusif Indonesia yang diukur dari pulau terluar lebarnya ....",opts:["200 mil laut","12 mil laut","3 mil laut","24 mil laut","100 mil laut"],a:0,ex:"ZEE 200 mil (UNCLOS 1982); 12 mil laut teritorial, 24 mil zona tambahan, 3 mil aturan lama."},
{id:"TWK-1968",q:"Kata baku dari 'apotik' adalah ....",opts:["apotek","apotik","apotheik","apotex","apotheek"],a:0,ex:"Bentuk baku: apotek; apotik tidak baku. Kata serapan disesuaikan dengan kaidah bahasa Indonesia."},
{id:"TWK-1969",q:"Kata baku dari 'antri' adalah ....",opts:["antre","antri","angtre","anter","antrei"],a:0,ex:"Bentuk baku: antre; lafal sehari-hari 'antri' tidak baku dalam tulisan resmi."},
{id:"TWK-1970",q:"Kata baku dari 'praktek' adalah ....",opts:["praktik","praktek","pratik","prakteek","practek"],a:0,ex:"Bentuk baku: praktik (serapan dari practijk); praktek tidak baku."},
{id:"TWK-1971",q:"Kata baku dari 'resiko' adalah ....",opts:["risiko","resiko","risico","riskio","reshiko"],a:0,ex:"Bentuk baku: risiko; penulisan 'resiko' tidak baku."},
{id:"TWK-1972",q:"Kata baku dari 'karir' adalah ....",opts:["karier","karir","carrer","karirr","kariir"],a:0,ex:"Bentuk baku: karier; 'karir' tidak baku dalam bahasa Indonesia."},
{id:"TWK-1973",q:"Kata baku dari 'analisa' adalah ....",opts:["analisis","analisa","analysa","analices","anallisa"],a:0,ex:"Bentuk baku: analisis (kata benda); 'analisa' tidak baku, sedangkan 'menganalisis' adalah kata kerja."},
{id:"TWK-1974",q:"Kata baku dari 'ijin' adalah ....",opts:["izin","ijin","idzin","ijjin","izien"],a:0,ex:"Bentuk baku: izin; 'ijin' tidak baku."},
{id:"TWK-1975",q:"Kata baku dari 'nasehat' adalah ....",opts:["nasihat","nasehat","nasyihat","nasiehat","nashiat"],a:0,ex:"Bentuk baku: nasihat; 'nasehat' tidak baku."},
{id:"TWK-1976",q:"Kata baku dari 'hutang' adalah ....",opts:["utang","hutang","uuthang","huttang","utangg"],a:0,ex:"Bentuk baku: utang (berutang, piutang); 'hutang' tidak baku."},
{id:"TWK-1977",q:"Kata baku dari 'goa' untuk lubang besar di bukit adalah ....",opts:["gua","goa","gowa","guha","goua"],a:0,ex:"Bentuk baku: gua; 'goa' tidak baku dalam bahasa Indonesia."},
{id:"TWK-1978",q:"Kalimat efektif adalah kalimat yang ....",opts:["hemat kata, padu, dan mudah dipahami","panjang dan menggunakan kata sulit","mengulang kata untuk penegasan","tanpa subjek agar ringkas","sebanyak-banyaknya menggunakan istilah asing"],a:0,ex:"Kalimat efektif: hemat, padu, jelas, logis; kalimat panjang berbelit, pengulangan, dan tanpa subjek justru tidak efektif."},
{id:"TWK-1979",q:"Kalimat berikut yang efektif adalah ....",opts:["Para siswa sedang berdiskusi di kelas","Para para siswa sedang berdiskusi di kelas","Demi untuk meningkatkan mutu, diadakan pelatihan","Adalah penting bagi kita semua untuk belajar","Para siswa mereka sedang berdiskusi di kelas"],a:0,ex:"Kalimat efektif hemat kata; pengulangan 'para para', 'demi untuk', 'adalah penting', dan subjek ganda tidak efektif."},
{id:"TWK-1980",q:"Kalimat 'Para siswa-siswa berkumpul di aula' dapat diperbaiki menjadi ....",opts:["Para siswa berkumpul di aula","Para para siswa berkumpul di aula","Siswa-siswa para berkumpul di aula","Para siswa-siswa mereka berkumpul","Berkumpul para siswa-siswa di aula"],a:0,ex:"'Para' sudah bermakna jamak sehingga 'siswa-siswa' tidak perlu diulang; cukup 'Para siswa berkumpul di aula'."},
{id:"TWK-1981",q:"Contoh penulisan huruf kapital yang benar adalah ....",opts:["Bulan Agustus","bulan Agustus","Bulan agustus","bulan agustus","BULAN agustus"],a:0,ex:"Nama bulan adalah nama diri sehingga huruf awal kapital: 'Bulan Agustus'; kata 'bulan' sebagai nama diri juga kapital."},
{id:"TWK-1982",q:"Penulisan nama orang dengan huruf kapital yang tepat adalah ....",opts:["Budi Santoso","budi Santoso","Budi santoso","budi santoso","BUDI santoso"],a:0,ex:"Nama diri (orang) ditulis dengan huruf kapital pada setiap unsur nama: 'Budi Santoso'."},
{id:"TWK-1983",q:"Penggunaan tanda baca koma yang tepat adalah ....",opts:["Saya membeli buku, pensil, dan penghapus","Saya membeli, buku pensil dan penghapus","Saya, membeli buku pensil dan penghapus","Saya membeli buku pensil, dan penghapus","Saya membeli buku, pensil dan, penghapus"],a:0,ex:"Koma memisahkan unsur pemerincian; tidak dipakai memisahkan subjek-predikat atau diletakkan sembarangan."},
{id:"TWK-1984",q:"Tanda baca titik dua digunakan untuk ....",opts:["mengakhiri pernyataan yang diikuti pemerincian","mengakhiri seluruh kalimat berita","memisahkan anak kalimat","menyatakan dialog langsung","menandai singkatan"],a:0,ex:"Titik dua dipakai sebelum pemerincian atau penjelasan; akhir kalimat berita memakai titik, dialog memakai tanda petik."},
{id:"TWK-1985",q:"Contoh penulisan kata depan 'di' yang benar adalah ....",opts:["di rumah","dirumah","di-rumah","diRumah","diRumah"],a:0,ex:"Kata depan 'di' (tempat) ditulis terpisah: 'di rumah'; 'dirumah' salah karena 'di-' sebagai imbuhan hanya untuk kata kerja pasif."},
{id:"TWK-1986",q:"Penulisan gabungan kata yang tepat adalah ....",opts:["tanggung jawab","tanggungjawab","tanggung-jawab","tanggungJawab","tanggong jawab"],a:0,ex:"Gabungan kata yang lazim: 'tanggung jawab' ditulis terpisah; bentuk rapat 'tanggungjawab' tidak baku."},
{id:"TWK-1987",q:"Contoh penulisan imbuhan 'di-' yang benar adalah ....",opts:["dibaca","di baca","di-baca","diBaca","di_baca"],a:0,ex:"Imbuhan 'di-' dirangkai dengan kata kerja: 'dibaca'; berbeda dengan kata depan 'di' yang ditulis terpisah."},
{id:"TWK-1988",q:"Kata serapan dari bahasa Inggris 'management' adalah ....",opts:["manajemen","management","managemen","manajeman","menagemen"],a:0,ex:"Serapan baku: manajemen; bentuk asing 'management' dan varian lain tidak baku."},
{id:"TWK-1989",q:"Kata serapan 'system' dalam bahasa Indonesia adalah ....",opts:["sistem","system","sistim","sistym","sisttem"],a:0,ex:"Serapan baku: sistem; 'sistim' dan bentuk asing tidak baku."},
{id:"TWK-1990",q:"Paragraf deduktif adalah paragraf yang ....",opts:["kalimat utamanya terletak di awal paragraf","kalimat utamanya terletak di akhir paragraf","tidak memiliki kalimat utama","kalimat utamanya di tengah paragraf","terdiri atas satu kalimat saja"],a:0,ex:"Deduktif = umum ke khusus (kalimat utama di awal); induktif = khusus ke umum (kalimat utama di akhir)."},
{id:"TWK-1991",q:"Kalimat utama paragraf induktif terletak pada ....",opts:["akhir paragraf","awal paragraf","tengah paragraf","setiap kalimat","tidak ada kalimat utama"],a:0,ex:"Paragraf induktif diawali uraian khusus dan disimpulkan di akhir sehingga kalimat utama di akhir paragraf."},
{id:"TWK-1992",q:"Ejaan yang disempurnakan (EYD) ditetapkan pada tahun ....",opts:["1972","1947","1957","1967","1990"],a:0,ex:"EYD ditetapkan 1972 menggantikan Ejaan Suwandi; Ejaan Van Ophuijsen 1901, Ejaan Republik (Soewandi) 1947."},
{id:"TWK-1993",q:"Penulisan singkatan 'atas nama' yang tepat adalah ....",opts:["a.n.","an.","a/n","A.N.","a n"],a:0,ex:"Singkatan 'atas nama' ditulis 'a.n.' dengan titik; bentuk lain tidak baku."},
{id:"TWK-1994",q:"Bentuk kata baku dari 'sekedar' adalah ....",opts:["sekadar","sekedar","sakedar","sekedarh","sekeudar"],a:0,ex:"Bentuk baku: sekadar; 'sekedar' tidak baku."},
{id:"TWK-1995",q:"Kata baku dari 'trampil' adalah ....",opts:["terampil","trampil","terampill","trampill","terampel"],a:0,ex:"Bentuk baku: terampil (keterampilan); 'trampil' tidak baku."},
{id:"TWK-1996",q:"Penggunaan huruf kapital untuk nama hari yang tepat adalah ....",opts:["hari Senin","hari senin","Hari senin","HARI Senin","hari senin"],a:0,ex:"Nama hari adalah nama diri: 'Senin' kapital; kata 'hari' sebagai kata umum tidak kapital."},
{id:"TWK-1997",q:"Penulisan bilangan bertingkat yang tepat adalah ....",opts:["abad ke-21","abad ke 21","abad ke21","abad ke.21","abad ke:21"],a:0,ex:"Bilangan bertingkat: 'ke-21' dengan tanda hubung; tanpa spasi setelah 'ke'."},
{id:"TWK-1998",q:"Penulisan kata tanya tempat yang baku adalah ....",opts:["di mana","dimana","di-mana","diMana","dimanakah"],a:0,ex:"'Di mana' (kata depan + kata tanya) ditulis terpisah; 'dimana' tidak baku, 'di manakah' boleh dengan partikel -kah."},
{id:"TWK-1999",q:"Imbuhan 'pe-' pada kata 'sapu' menjadi ....",opts:["penyapu","pesapu","penyapukan","menyapu","disapu"],a:0,ex:"pe- + sapu → penyapu (peluluhan s menjadi ny); 'menyapu' kata kerja aktif, 'disapu' kata kerja pasif."},
{id:"TWK-2000",q:"Kalimat yang menggunakan ejaan tepat adalah ....",opts:["Mereka pergi ke pasar pada pagi hari","mereka Pergi ke pasar pada Pagi hari","Mereka pergi ke Pasar pada pagi Hari","Mereka pergi kepasar pada pagi hari","Mereka pergi ke pasar, pada pagi hari"],a:0,ex:"Huruf kapital hanya di awal kalimat; 'pasar' dan 'hari' bukan nama diri; 'ke pasar' terpisah; koma tidak dipakai sebelum keterangan waktu."},
];
